#!/usr/bin/env node
import fs from 'node:fs/promises';
import path from 'node:path';

const root = process.cwd();
const specsDir = path.join(root, '.ucmcp/specs');
const catalogDir = path.join(root, 'catalog');

const pp = (p) => p.replace(/\{([^}]+)\}/g, '{$1}');
const pathParams = (p) => [...p.matchAll(/\{([^}]+)\}/g)].map((m) => m[1]);

function op(operationId, method, p, summary, tags = []) {
  return {
    operationId,
    method,
    path: pp(p),
    summary,
    tags,
    parameters: pathParams(p).map((name) => ({ name, in: 'path', required: true, schema: { type: 'string' } }))
  };
}

function toSpec(def) {
  const operations = def.operations;
  const operationMap = Object.fromEntries(operations.map((o) => [o.operationId, { method: o.method, path: o.path }]));
  return {
    apiId: def.apiId,
    title: def.title,
    version: def.version,
    baseUrl: def.baseUrl,
    operations,
    operationMap,
    schemas: {}
  };
}

