await fs.mkdir(specsDir, { recursive: true });
await fs.mkdir(catalogDir, { recursive: true });

for (const api of apis) {
  const spec = toSpec(api);
  await fs.writeFile(path.join(specsDir, `${api.apiId}.json`), JSON.stringify(spec, null, 2) + '\n');
  const host = new URL(api.baseUrl.replace('{instance}','example').replace('{shop}','example').replace('{subdomain}','example').replace('{dc}','us1')).hostname;
  const authHeaderName = api.auth.toLowerCase().includes('x-api-key') ? 'x-api-key' : api.auth.toLowerCase().includes('client-id') ? 'authorization' : 'authorization';
  const prefix = api.auth.toLowerCase().includes('none') ? '' : api.auth.toLowerCase().includes('x-api-key') ? '' : (api.auth.toLowerCase().includes('bot') ? 'Bot ' : 'Bearer ');
  const catalog = { apiId: api.apiId, sourceUrl: api.sourceUrl, baseUrl: api.baseUrl, allowedHosts: [host], auth: { headerName: authHeaderName, prefix } };
  await fs.writeFile(path.join(catalogDir, `${api.apiId}.json`), JSON.stringify(catalog, null, 2) + '\n');
}

const lines = ['# API Catalog', '', `Total APIs: ${apis.length}`, '', '| API | Endpoints | Auth | Source | Base URL |', '|---|---:|---|---|---|'];
for (const api of apis) {
  lines.push(`| ${api.title} (${api.apiId}) | ${api.operations.length} | ${api.auth} | ${api.sourceUrl ? 'Official/Open docs' : 'Manual'} | ${api.baseUrl} |`);
}
await fs.writeFile(path.join(root, 'CATALOG.md'), lines.join('\n') + '\n');

console.log(`Generated ${apis.length} specs + catalog entries + CATALOG.md`);
